def do_algebra(operator, operand):
    import operator as op

    if len(operator) != len(operand) - 1:
        raise ValueError("The length of operator list must be one less than the operand list.")

    expression = operand[0]
    for i in range(len(operator)):
        expr_part = operand[i + 1]
        if operator[i] == '+':
            expression = expression + expr_part
        elif operator[i] == '-':
            expression = expression - expr_part
        elif operator[i] == '*':
            expression = expression * expr_part
        elif operator[i] == '//':
            expression = expression // expr_part
        elif operator[i] == '**':
            expression = expression ** expr_part
        else:
            raise ValueError(f"Unsupported operator: {operator[i]}")

    return expression
```

